package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Boolean;
    in attribute io_1 : Integer;
    in attribute io_2 : Integer;
    in attribute io_2_valid : Boolean;
    attribute count : Integer := 0;
    attribute previousPressed : Boolean := false;
    attribute pendingReport : Boolean := false;
    perform action tick {
      first start;
      then if ((io_0) and ((not previousPressed))) {
        first start;
        then assign count := count + 1;
        then assign pendingReport := true;
      } else {
        first start;
        then assign pendingReport := false;
      }
      then assign previousPressed := io_0;
    }
    out attribute serial_0_trigger : Boolean = pendingReport;
    out attribute serial_0_value_0 : Integer = count;
  }
  part system : Controller;
}
